fn decode_ldst_pac(bits: u32) -> Result<Instruction, DecodeError> {
    if bits & 0xff200400 != 0xf8200400 {
        return Err(DecodeError::Unallocated);
    }
    // size=11|111|VR=0|00|M=x|S=x|1|imm9=xxxxxxxxx|W=x|1|Rn=xxxxx|Rt=xxxxx
    let Rt: u8 = (bits & 0x1f) as u8;
    let Rn: u8 = ((bits >> 5) & 0x1f) as u8;
    let S: u8 = ((bits >> 22) & 0x1) as u8;
    let imm9: u16 = ((bits >> 12) & 0x1ff) as u16;
    let S10: u16 = (S as u16) << 9 | imm9;
    let offset: i64 = asl::SInt(13, (S10 as u128) << 3) as i64;
    match bits & 0xc4800800 {
        0xc0000000 => {
            // LDRAA, LDRAB — Key A, offset
            // LDRAA  <Xt>, [<Xn|SP>{, #<simm>}]
            Ok(Instruction::Ldraa64LdstPac {
                Xt: Rt.into(),
                Xn: Rn.into(),
                simm: offset,
            })
        }
        0xc0000800 => {
            // LDRAA, LDRAB — Key A, pre-indexed
            // LDRAA  <Xt>, [<Xn|SP>{, #<simm>}]!
            let unpredictable: bool = Rn == Rt && Rn != 31;
            Ok(Instruction::Ldraa64wLdstPac {
                Xt: Rt.into(),
                Xn: Rn.into(),
                simm: offset,
                unpredictable,
            })
        }
        0xc0800000 => {
            // LDRAA, LDRAB — Key B, offset
            // LDRAB  <Xt>, [<Xn|SP>{, #<simm>}]
            Ok(Instruction::Ldrab64LdstPac {
                Xt: Rt.into(),
                Xn: Rn.into(),
                simm: offset,
            })
        }
        0xc0800800 => {
            // LDRAA, LDRAB — Key B, pre-indexed
            // LDRAB  <Xt>, [<Xn|SP>{, #<simm>}]!
            let unpredictable: bool = Rn == Rt && Rn != 31;
            Ok(Instruction::Ldrab64wLdstPac {
                Xt: Rt.into(),
                Xn: Rn.into(),
                simm: offset,
                unpredictable,
            })
        }
        _ => Err(DecodeError::Unallocated),
    }
}

